// Plays sound effects and background music, and keeps the player's audio settings.
// All sounds are generated by design/sound/build.js. Audio is best-effort: failures are ignored.
import { useEffect, useState } from 'react';
import { AppState, Platform } from 'react-native';
import { createAudioPlayer, setAudioModeAsync } from 'expo-audio';
import type { AudioPlayer } from 'expo-audio';
import { DEFAULT_SOUND_SETTINGS, normalizeSoundSettings } from '../logic/soundSettings';
import type { SoundSettings } from '../logic/soundSettings';
import { readJson, writeJson } from './storage';

const SFX = {
  click: require('../../assets/sounds/click.wav'),
  step1: require('../../assets/sounds/step1.wav'),
  step2: require('../../assets/sounds/step2.wav'),
  zstep: require('../../assets/sounds/zstep.wav'),
  heartbeat: require('../../assets/sounds/heartbeat.wav'),
  groan: require('../../assets/sounds/groan.wav'),
  bite: require('../../assets/sounds/bite.wav'),
  infected: require('../../assets/sounds/infected.wav'),
  heal: require('../../assets/sounds/heal.wav'),
  shield: require('../../assets/sounds/shield.wav'),
  task: require('../../assets/sounds/task.wav'),
  checkpoint: require('../../assets/sounds/checkpoint.wav'),
  hurt: require('../../assets/sounds/hurt.wav'),
  throw: require('../../assets/sounds/throw.wav'),
  stoneHit: require('../../assets/sounds/stoneHit.wav'),
  released: require('../../assets/sounds/released.wav'),
  ability: require('../../assets/sounds/ability.wav'),
  tick: require('../../assets/sounds/tick.wav'),
  win: require('../../assets/sounds/win.wav'),
  lose: require('../../assets/sounds/lose.wav'),
} as const;
export type SfxId = keyof typeof SFX;

const MUSIC = {
  menu: { source: require('../../assets/sounds/music-menu.wav'), gain: 0.6 },
  game: { source: require('../../assets/sounds/music-game.wav'), gain: 1 },
} as const;
export type MusicId = keyof typeof MUSIC;

const FOOTSTEPS: SfxId[] = ['step1', 'step2', 'zstep'];
/** Sounds that can overlap get several players; the rest restart. */
const POOL_SIZE: Partial<Record<SfxId, number>> = { step1: 2, step2: 2, zstep: 2, click: 2, bite: 2, stoneHit: 2, groan: 2 };
const STORAGE_KEY = 'zt.soundSettings';

let settings: SoundSettings = DEFAULT_SOUND_SETTINGS;
const listeners = new Set<(s: SoundSettings) => void>();
const pools = new Map<SfxId, { players: AudioPlayer[]; next: number }>();
const lastPlayed = new Map<SfxId, number>();
let music: { id: MusicId; player: AudioPlayer } | null = null;
let wantedMusic: MusicId | null = null;
let appActive = true;
let started = false;

function safe(fn: () => unknown) {
  try {
    const r = fn();
    if (r && typeof (r as Promise<unknown>).catch === 'function') (r as Promise<unknown>).catch(() => {});
  } catch {
    // Audio is a nice-to-have.
  }
}

function playerFor(id: SfxId): AudioPlayer | null {
  let pool = pools.get(id);
  if (!pool) {
    pool = { players: [], next: 0 };
    try {
      for (let i = 0; i < (POOL_SIZE[id] ?? 1); i++) pool.players.push(createAudioPlayer(SFX[id]));
    } catch {
      return null;
    }
    pools.set(id, pool);
  }
  const p = pool.players[pool.next];
  pool.next = (pool.next + 1) % pool.players.length;
  return p ?? null;
}

/** Plays a sound effect. `volume` (0..1) is scaled by the player's effects volume. */
export function playSfx(id: SfxId, volume = 1) {
  if (settings.muted || settings.sfx <= 0 || volume <= 0.01) return;
  if (!settings.footsteps && FOOTSTEPS.includes(id)) return;
  const now = Date.now();
  if (now - (lastPlayed.get(id) ?? 0) < 45) return;
  lastPlayed.set(id, now);
  const p = playerFor(id);
  if (!p) return;
  safe(() => {
    p.volume = Math.min(1, settings.sfx * volume);
    safe(() => p.seekTo(0));
    p.play();
  });
}

function applyMusic() {
  const volume = settings.muted || !appActive ? 0 : settings.music;
  if (!wantedMusic || volume <= 0) {
    if (music) safe(() => music!.player.pause());
    return;
  }
  if (music?.id !== wantedMusic) {
    if (music) safe(() => music!.player.remove());
    music = null;
    try {
      const player = createAudioPlayer(MUSIC[wantedMusic].source);
      player.loop = true;
      music = { id: wantedMusic, player };
    } catch {
      return;
    }
  }
  const m = music;
  safe(() => {
    m.player.volume = volume * MUSIC[m.id].gain;
    m.player.play();
  });
}

/** Chooses the background track (null for silence). Safe to call repeatedly. */
export function setMusic(id: MusicId | null) {
  if (id === wantedMusic) return;
  wantedMusic = id;
  applyMusic();
}

export function getSoundSettings(): SoundSettings {
  return settings;
}

export function updateSoundSettings(patch: Partial<SoundSettings>) {
  settings = normalizeSoundSettings({ ...settings, ...patch });
  listeners.forEach((l) => l(settings));
  applyMusic();
  writeJson(STORAGE_KEY, settings).catch(() => {});
}

export function useSoundSettings(): SoundSettings {
  const [s, setS] = useState(settings);
  useEffect(() => {
    listeners.add(setS);
    setS(settings);
    return () => {
      listeners.delete(setS);
    };
  }, []);
  return s;
}

/** Loads saved settings and sets up audio. Call once when the app starts. */
export function initSound() {
  if (started) return;
  started = true;
  safe(() => setAudioModeAsync({ playsInSilentMode: true, shouldPlayInBackground: false, interruptionMode: 'mixWithOthers' }));
  readJson<unknown>(STORAGE_KEY, null).then((raw) => {
    settings = normalizeSoundSettings(raw);
    listeners.forEach((l) => l(settings));
    applyMusic();
  });
  AppState.addEventListener('change', (state) => {
    appActive = state === 'active';
    applyMusic();
  });
  // Browsers block audio until the first tap or key press, so retry the music then.
  if (Platform.OS === 'web') {
    const doc = (globalThis as unknown as { document?: { addEventListener: (t: string, f: () => void, o?: object) => void } }).document;
    let unlocked = false;
    const unlock = () => {
      if (unlocked) return;
      unlocked = true;
      if (music) safe(() => music!.player.remove());
      music = null;
      applyMusic();
    };
    doc?.addEventListener('pointerdown', unlock, { once: true });
    doc?.addEventListener('keydown', unlock, { once: true });
  }
}
